const D = { scale:1, energy:.6, hue:28, speed:1, density:.5, x:.5, y:.30, chub:.5, limb:.5, sleepy:.55, pose:'hang', style:'felt', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const m = u * P.scale;
const L = (a,b,t)=>a+(b-a)*t;
const clamp = (v,a,b)=>v<a?a:v>b?b:v;
const fr = i => { const v = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return v - Math.floor(v); };
const TAU = Math.PI*2;
const sty = P.style;

// ---- seed / density keyed felt fibers ----
if (S.seedUsed !== P.seed || S.densUsed !== P.density) {
  S.seedUsed = P.seed; S.densUsed = P.density;
  const nf = Math.round(24 + P.density*70);
  S.fib = [];
  for (let i=0;i<nf;i++) S.fib.push({ a:fr(i+3)*TAU, r:Math.sqrt(fr(i+9)), len:.4+fr(i+21)*.9, ang:fr(i+31)*TAU, sh:fr(i+41) });
}

// ---- half-tempo rhythm (sloth moves at K.beat/2) ----
if (S.lastBeat==null || K.beat < S.lastBeat) S.lastBeat = K.beat;
S.lastBeat = K.beat;
const bt = K.beat * P.speed * 0.5;
const en = P.energy;
const chub = P.chub, limb = P.limb, sleepy = P.sleepy;
const pose = P.pose;
const breath = 1 + (K.swell*.5 + A.rms*.7)*(.04 + en*.05);

// pendulum swing about the branch grip (whole silhouette translates)
const ampBase = .16 + en*.20;
const swingAmp = ampBase * (pose==='idle'?.55 : pose==='dance'?1.25 : pose==='wave'?.8 : 1);
const swing = Math.sin(bt*Math.PI)*swingAmp + Math.sin(bt*Math.PI*.5)*.03 + A.bass*.06;

// blissful blink — mostly half-lidded, rare full blink, fps-independent
const bc = (K.t*0.42 + fr(2)) % 3.4;
const blink = bc < 0.15 ? 1 : 0;
const eyeOpen = clamp(L(.5,.12,sleepy)*(1-blink), 0, 1);

// dims (relative to hero m)
const armL = .175*m*L(.75,1.4,limb);
const torW = .21*m*L(.85,1.35,chub);
const torH = .27*m*L(.95,1.15,chub);
const headR = .115*m*L(.9,1.15,chub);
const legL = .155*m*L(.8,1.3,limb);
const px = P.x*width, py = P.y*height;
const sw = u*0.0055*P.scale;

// ---- style paint helper (shade 0..1 = dark..light for modeling) ----
function paint(shade, edge){
  if (sty==='contour'){ noFill(); stroke(P.hue,42,90,92); strokeWeight(sw*.85); }
  else if (sty==='noir'){ noStroke(); fill(P.hue,11, L(9,96,clamp(shade,0,1))); }
  else if (sty==='sketch'){ fill(44,7,96); stroke(P.hue,34,26,80); strokeWeight(sw*.55); }
  else { // felt — muted wool with soft darker rim
    if (edge){ stroke(P.hue,36, L(30,50,shade),70); strokeWeight(sw*.5); }
    else noStroke();
    fill(P.hue,30, L(48,80,clamp(shade,0,1)));
  }
}
function capsule(x1,y1,x2,y2,w,shade){
  const mx=(x1+x2)/2,my=(y1+y2)/2,dx=x2-x1,dy=y2-y1;
  const len=Math.hypot(dx,dy),ang=Math.atan2(dy,dx);
  push(); translate(mx,my); rotate(ang); paint(shade,true); ellipse(0,0,len+w,w); pop();
}

push();
translate(px,py);

// ---- branch (screen space, does NOT swing) ----
const brW = m*0.95, brY = -headR*0.18;
push();
if (sty==='contour'){ noFill(); stroke(P.hue,42,90,92); strokeWeight(sw*.85);
  line(-brW/2,brY,brW/2,brY); }
else if (sty==='noir'){ noStroke(); fill(28,14,26); rectMode(CENTER); rect(0,brY,brW,m*.045,m*.02); }
else if (sty==='sketch'){ noFill(); stroke(P.hue,34,26,80); strokeWeight(sw*.7); rectMode(CENTER); rect(0,brY,brW,m*.045,m*.02); }
else { noStroke(); fill(26,44,40); rectMode(CENTER); rect(0,brY,brW,m*.05,m*.02);
  fill(26,44,32); for(let i=0;i<5;i++){ const bx=(fr(i+70)-.5)*brW*.8; ellipse(bx,brY,m*.02,m*.03);} }
pop();

// ---- body swings about the grip (origin) ----
rotate(swing);
scale(1, breath);

// grip claws hooking the branch
paint(.25,true);
for (const s of [-1,1]){ push(); translate(s*torW*0.16, brY); rotate(s*.3);
  arc(0,0,m*.06,m*.09,Math.PI,TAU); pop(); }

// layout points below grip
const shY = armL*0.52;
const headY = shY + headR*0.55;
const torY = headY + headR*0.5 + torH*0.5;
const legTopY = torY + torH*0.4;

// arms: grip(origin) -> shoulders
const waveA = pose==='wave' ? Math.sin(bt*Math.PI*2) : 0;
capsule(-torW*0.16, 0, -torW*0.62, shY, m*.075, .55);
if (pose==='wave'){
  const hx = torW*(0.7+waveA*0.28), hy = -headR*0.6 - Math.abs(waveA)*headR*0.4;
  capsule(torW*0.16,0, torW*0.5,shY*0.4, m*.07,.55);
  capsule(torW*0.5,shY*0.4, hx,hy, m*.062,.62);
} else {
  capsule(torW*0.16, 0, torW*0.62, shY, m*.075, .55);
}

// legs (relaxed / dancing kick)
const kick = (pose==='dance'?1:.35);
for (const s of [-1,1]){
  const la = Math.sin(bt*Math.PI + (s>0?0:Math.PI))*.16*kick;
  const hipX=s*torW*0.42, hipY=legTopY;
  const ftX=hipX + Math.sin(la)*legL*0.5, ftY=hipY+Math.cos(la)*legL;
  capsule(hipX,hipY, ftX,ftY, m*.07, .5);
  paint(.3,true); push(); translate(ftX,ftY); ellipse(s*m*.01,0,m*.075,m*.055); pop();
}

// torso — teardrop
paint(.62,true);
if (sty==='contour'){ noFill(); }
push(); translate(0,torY);
beginShape();
vertex(0,-torH*0.5);
bezierVertex(torW*0.62,-torH*0.42, torW*0.6,torH*0.4, 0,torH*0.5);
bezierVertex(-torW*0.6,torH*0.4, -torW*0.62,-torH*0.42, 0,-torH*0.5);
endShape(CLOSE);
// felt belly patch / modeling
if (sty==='felt'){ noStroke(); fill(P.hue,20,86); ellipse(0,torH*0.08,torW*0.7,torH*0.62); }
if (sty==='noir'){ noStroke(); fill(P.hue,11,78,55); ellipse(-torW*0.2,-torH*0.15,torW*0.55,torH*0.5); }
pop();

// felt fiber stipple / sketch hatch on torso
if (sty==='felt'){ noStroke();
  for (const f of S.fib){ const fx=Math.cos(f.a)*f.r*torW*0.52, fy=torY+Math.sin(f.a)*f.r*torH*0.5;
    fill(P.hue,28, f.sh>.5?86:58, 55); ellipse(fx,fy,sw*.7,sw*1.1); } }
else if (sty==='sketch'){ stroke(P.hue,30,30,45); strokeWeight(sw*.35);
  for(let i=0;i<11;i++){ const yy=torY-torH*0.4+i*(torH*0.8/10); line(-torW*0.4,yy, torW*0.45,yy+torW*0.25);} }

// ---- head ----
push(); translate(0,headY);
const nod = Math.sin(bt*Math.PI*.5)*.05;
rotate(nod);
paint(.68,true);
ellipse(0,0,headR*2.0,headR*1.8);
// snout
paint(.6,true); ellipse(0,headR*0.55,headR*1.15,headR*0.95);
// sloth face mask (dark eye patches) — the signature look
if (sty!=='contour'){
  noStroke();
  const mk = sty==='noir'?color(P.hue,10,22):sty==='sketch'?color(P.hue,30,30,60):color(P.hue,38,34);
  fill(mk);
  for (const s of [-1,1]){ push(); translate(s*headR*0.5,-headR*0.1); rotate(s*.5);
    ellipse(0,0,headR*0.85,headR*1.15); pop(); }
  // brow stripe
  fill(mk); ellipse(0,-headR*0.72,headR*1.5,headR*0.5);
}
// eyes
for (const s of [-1,1]){ push(); translate(s*headR*0.5,-headR*0.05);
  if (eyeOpen>0.05){ paint(.95); if(sty==='noir'){noStroke();fill(0,0,98);} if(sty==='contour'){noFill();stroke(P.hue,42,90,92);strokeWeight(sw*.7);}
    ellipse(0,0,headR*0.5,headR*0.5*L(.4,1,eyeOpen));
    if (sty!=='contour'){ noStroke(); fill(P.hue,50,12); ellipse(0,0,headR*0.24,headR*0.24*L(.4,1,eyeOpen)); }
  } else { stroke(sty==='noir'?color(0,0,80):color(P.hue,40,25)); strokeWeight(sw*.7); noFill();
    arc(0,0,headR*0.5,headR*0.4,0.15,Math.PI-0.15); }
  pop(); }
// nose + sleepy smile
if (sty!=='contour'){ noStroke(); fill(sty==='noir'?color(0,0,15):color(P.hue,45,22));
  ellipse(0,headR*0.42,headR*0.34,headR*0.24); }
stroke(sty==='noir'?color(0,0,72):color(P.hue,42,26)); strokeWeight(sw*.6); noFill();
arc(0,headR*0.66,headR*0.6,headR*0.4,0.25,Math.PI-0.25);
pop(); // head

pop(); // body swing

// ---- floating sleep Z's (constant drift; comedic; aids never-static) ----
if (pose!=='dance' && sty!=='contour' && sty!=='sketch'){
  const nz = 1 + Math.round(P.density*2);
  push(); textAlign(CENTER,CENTER);
  for (let i=0;i<nz;i++){ const ph=(K.t*0.24 + i*0.34 + fr(i+8))%1;
    const zx=px + m*0.30 + ph*m*0.16 + Math.sin(ph*6+i)*m*0.02;
    const zy=py + m*0.06 - ph*m*0.34;
    noStroke(); fill(P.hue,22,96,(1-ph)*72);
    textSize(m*(0.045+ph*0.06)); text('z',zx,zy); }
  pop();
}
